from unittest.mock import Mock
from uuid import UUID, uuid4

import httpx
import pytest
import weaviate.classes as wvc

from weaviate_agents.personalization.personalization_agent import (
    PersonalizationAgent,
    PersonalizationAgentGetObjectsResponse,
    PersonalizedQuery,
)


class DummyClient:
    """A dummy client to simulate the Weaviate client for testing purposes."""

    def __init__(self):
        self._connection = self  # Simulate connection
        self.url = "http://test-url:443"  # Add url attribute
        self.additional_headers = {"Authorization": "test-token"}

    def get_current_bearer_token(self) -> str:
        """Simulate bearer token retrieval from connection.

        Returns:
            str: The test bearer token prefixed with 'Bearer '.
        """
        return "Bearer test-token"


@pytest.fixture
def agent() -> PersonalizationAgent:
    return PersonalizationAgent(
        client=DummyClient(),  # type: ignore
        reference_collection="TestCollection",
    )


def test_query(agent: PersonalizationAgent):
    query = agent.query(persona_id=uuid4())
    assert isinstance(query, PersonalizedQuery)


@pytest.mark.parametrize(
    "filters, filter_request",
    [
        (None, None),
        (
            wvc.query.Filter.by_property("title").not_equal("Avatar"),
            {"operator": "NotEqual", "target": "title", "value": "Avatar"},
        ),
        (
            (
                wvc.query.Filter.by_property("title").not_equal("Avatar")
                & wvc.query.Filter.by_property("genres").not_equal("comedy")
            ),
            {
                "combine": "and",
                "filters": [
                    {"operator": "NotEqual", "target": "title", "value": "Avatar"},
                    {"operator": "NotEqual", "target": "genres", "value": "comedy"},
                ],
            },
        ),
    ],
)
def test_get_objects(agent: PersonalizationAgent, monkeypatch, filters, filter_request):
    mock_response = {
        "objects": [
            {
                "uuid": "ae0fc31d-2f11-4e3a-a0f8-6e64795d7db9",
                "original_rank": 0,
                "personalized_rank": None,
                "properties": {
                    "title": "The Crush",
                    "genres": ["Drama", "Thriller", "Horror"],
                },
            },
            {
                "uuid": "f557e407-74db-453a-95b4-9357045be38d",
                "original_rank": 1,
                "personalized_rank": None,
                "properties": {
                    "title": "Armed Response",
                    "genres": ["Action", "Horror", "Thriller"],
                },
            },
        ],
        "ranking_rationale": None,
        "usage": {
            "requests": 0,
            "request_tokens": 0,
            "response_tokens": 0,
            "total_tokens": 0,
            "details": None,
        },
    }

    mock_httpx = Mock()
    mock_httpx.post.return_value = httpx.Response(
        status_code=200,
        request=httpx.Request("post", "http://dummy-agent"),
        json=mock_response,
    )
    monkeypatch.setattr(
        "weaviate_agents.personalization.personalization_agent.httpx", mock_httpx
    )

    persona_id = UUID("32a31598-42a8-4ed2-92d0-1273c7dbdcb0")
    recommendations = agent.get_objects(
        persona_id=persona_id,
        filters=filters,
    )
    expected_request = {
        "objects_request": {
            "persona_id": "32a31598-42a8-4ed2-92d0-1273c7dbdcb0",
            "limit": 10,
            "recent_interactions_count": 100,
            "exclude_interacted_items": True,
            "decay_rate": 0.1,
            "exclude_items": [],
            "use_agent_ranking": True,
            "explain_results": True,
            "instruction": None,
            "filters": filter_request,
        },
        "personalization_request": {
            "collection_name": "TestCollection",
            "headers": {"Authorization": "test-token"},
            "item_collection_vector_name": None,
            "create": False,
        },
    }

    mock_httpx.post.assert_called_once()
    request_json = mock_httpx.post.call_args.kwargs["json"]
    assert request_json == expected_request

    assert isinstance(recommendations, PersonalizationAgentGetObjectsResponse)
    assert recommendations.model_dump(mode="json") == mock_response

from __future__ import annotations

from typing import Annotated, List, Literal, Optional, Union

from pydantic import BaseModel, ConfigDict, PlainSerializer
from typing_extensions import TypedDict
from weaviate.classes.query import Move
from weaviate.collections.classes.filters import (
    _FilterAnd,
    _FilterOr,
    _Filters,
)
from weaviate.collections.classes.grpc import (
    HybridVectorType,
    NearVectorInputType,
    _HybridNearText,
    _HybridNearVector,
)


class _MoveSerialise(TypedDict):
    force: float
    objects: Optional[List[str]]
    concepts: Optional[List[str]]


@PlainSerializer
def serialise_move(move: Optional[Move]) -> Optional[_MoveSerialise]:
    if move is None:
        return None
    return _MoveSerialise(
        force=move.force, objects=move._objects_list, concepts=move._concepts_list
    )


class _FilterAndOrSerialise(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)

    combine: Literal["and", "or"]
    filters: list[Union[_Filters, _FilterAndOrSerialise]]


@PlainSerializer
def serialise_filter(
    filter_and_or_value: _Filters,
) -> Union[_Filters, _FilterAndOrSerialise]:
    return _serialise_filter_level(filter_and_or_value)


def _serialise_filter_level(
    filter_and_or_value: _Filters,
) -> Union[_Filters, _FilterAndOrSerialise]:
    if not isinstance(filter_and_or_value, (_FilterAnd, _FilterOr)):
        return filter_and_or_value

    combine: Literal["and", "or"] = (
        "and" if isinstance(filter_and_or_value, _FilterAnd) else "or"
    )
    return _FilterAndOrSerialise(
        combine=combine,
        filters=[_serialise_filter_level(f) for f in filter_and_or_value.filters],
    )


# A set of models to help serialise HybridVectorType, which is a union of
# NearVectorInputType (itself a union over std types), _HybridNearText and _HybridNearVector.
class _HybridNearTextSerialise(_HybridNearText):
    serialised_class: Literal["_HybridNearText"] = "_HybridNearText"

    move_to: Annotated[Optional[Move], serialise_move] = None
    move_away: Annotated[Optional[Move], serialise_move] = None


def _serialise_hybrid_near_text(model: _HybridNearText) -> _HybridNearTextSerialise:
    return _HybridNearTextSerialise.model_validate(model.model_dump())


class _HybridNearVectorSerialise(BaseModel):
    serialised_class: Literal["_HybridNearVector"] = "_HybridNearVector"

    vector: NearVectorInputType
    distance: Optional[float]
    certainty: Optional[float]


def _serialise_hybrid_near_vector(
    model: _HybridNearVector,
) -> _HybridNearVectorSerialise:
    return _HybridNearVectorSerialise(
        vector=model.vector,
        distance=model.distance,
        certainty=model.certainty,
    )


@PlainSerializer
def serialise_hybrid_vector_type(
    vector: HybridVectorType,
) -> Union[_HybridNearTextSerialise, _HybridNearVectorSerialise, NearVectorInputType]:
    if isinstance(vector, _HybridNearText):
        return _serialise_hybrid_near_text(vector)
    elif isinstance(vector, _HybridNearVector):
        return _serialise_hybrid_near_vector(vector)
    else:
        return vector

from typing import TYPE_CHECKING, Union

from rich.console import Console
from rich.panel import Panel
from rich.pretty import Pretty
from rich.table import Table

if TYPE_CHECKING:
    from weaviate_agents.query.classes import (
        AskModeResponse,
        ParsedAskModeResponse,
        QueryAgentResponse,
    )

console = Console()


def print_query_agent_response(response: "QueryAgentResponse"):
    """Prints a formatted response from the Query Agent using rich."""
    console.print(
        Panel(
            response.original_query,
            title="🔍 Original Query",
            padding=1,
        )
    )

    console.print(
        Panel(response.final_answer, title="📝 Final Answer", style="cyan", padding=1)
    )

    for collection_searches in response.searches:
        for i, result in enumerate(collection_searches):
            console.print(
                Panel(
                    Pretty(result),
                    title=f"🔭 Searches Executed {i+1}/{len(collection_searches)}",
                    style="white",
                    padding=1,
                )
            )
    if len(response.searches) == 0:
        console.print(Panel("🔭 No Searches Run", style="indian_red", padding=1))

    for collection_aggs in response.aggregations:
        for i, agg in enumerate(collection_aggs):
            console.print(
                Panel(
                    Pretty(agg),
                    title=f"📊 Aggregations Run {i+1}/{len(collection_aggs)}",
                    style="white",
                    padding=1,
                )
            )
    if len(response.aggregations) == 0:
        console.print(Panel("📊 No Aggregations Run", style="indian_red", padding=1))

    if response.missing_information:
        title = (
            "⚠️ Answer is Partial - Missing Information:"
            if response.is_partial_answer
            else "⚠️ Missing Information:"
        )
        missing_info = []
        for missing in response.missing_information:
            missing_info.append(f"- {missing}")

        console.print(
            Panel("\n".join(missing_info), title=title, style="yellow", padding=1)
        )

    sources = []
    for source in response.sources:
        sources.append(f" - {source}")
    if sources:
        console.print(
            Panel("\n".join(sources), title="📚 Sources", style="white", padding=1)
        )

    print("\n")

    table = Table(title="📊 Usage Statistics", show_header=False)
    table.add_row("LLM Requests:", str(response.usage.requests))
    table.add_row("Input Tokens:", str(response.usage.request_tokens))
    table.add_row("Output Tokens:", str(response.usage.response_tokens))
    table.add_row("Total Tokens:", str(response.usage.total_tokens))
    console.print(table)

    console.print(
        f"\n[bold]Total Time Taken:[/bold] {response.total_time:.2f}s", style="cyan"
    )


def print_ask_mode_response(
    response: Union["AskModeResponse", "ParsedAskModeResponse"],
):
    """Prints a formatted response from the Ask Mode using rich."""
    if hasattr(response, "final_answer_parsed"):
        console.print(
            Panel(
                Pretty(response.final_answer_parsed),
                title="💬 Ask Mode Response",
                style="cyan",
                padding=1,
            )
        )
    else:
        console.print(
            Panel(
                response.final_answer,
                title="💬 Ask Mode Response",
                style="cyan",
                padding=1,
            )
        )

    for i, result in enumerate(response.searches):
        search_content = Pretty(result)
        console.print(
            Panel(
                search_content,
                title=f"🔭 Search {i+1}/{len(response.searches)}",
                style="white",
                padding=1,
            )
        )

    if len(response.searches) == 0:
        console.print(Panel("🔭 No Searches Run", style="indian_red", padding=1))

    for i, agg in enumerate(response.aggregations):
        agg_content = Pretty(agg)
        console.print(
            Panel(
                agg_content,
                title=f"📊 Aggregation {i+1}/{len(response.aggregations)}",
                style="white",
                padding=1,
            )
        )

    if len(response.aggregations) == 0:
        console.print(Panel("📊 No Aggregations Run", style="indian_red", padding=1))

    if response.missing_information:
        title = (
            "⚠️ Answer is Partial - Missing Information:"
            if response.is_partial_answer
            else "⚠️ Missing Information:"
        )
        missing_info = []
        for missing in response.missing_information:
            missing_info.append(f"- {missing}")

        console.print(
            Panel("\n".join(missing_info), title=title, style="yellow", padding=1)
        )

    if response.sources:
        sources = []
        for source in response.sources:
            sources.append(f" - {source}")
        console.print(
            Panel("\n".join(sources), title="📚 Sources", style="white", padding=1)
        )

    print("\n")

    table = Table(title="📊 Usage Statistics", show_header=False)
    table.add_row("Model Units:", str(response.usage.model_units))
    table.add_row("Usage in Plan:", str(response.usage.usage_in_plan))
    table.add_row(
        "Remaining Plan Requests:", str(response.usage.remaining_plan_requests)
    )
    console.print(table)

    console.print(
        f"\n[bold]Total Time Taken:[/bold] {response.total_time:.2f}s", style="cyan"
    )
